INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc3216718d9735bc9cbedd4122723dcc', 'NEET', '12', 'Biology', 'bio_12_neet_human_reproduction', 'Human Reproduction', 'Fetal heart auscultation', '[]', '["gestation","fetal heart","Doppler auscultation","developmental milestones","prenatal care"]', 0, 0, '[]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 3, -1.0, 'At which week of gestation does the fetal heart become audible with a Doppler device?', '["6 weeks", "8 weeks", "10 weeks", "12 weeks"]', '10 weeks', 'The fetal cardiac activity can be detected by ultrasound as early as 6–7 weeks, but the sound of the heartbeat becomes audible with a Doppler device around 10 weeks of gestation.', '["Step 1: Recall the timeline of fetal cardiac development.", "Step 2: Identify the gestational age when Doppler auscultation is feasible.", "Step 3: Choose the corresponding option."]', '', 'biology.reproduction.fetal_heart_timing', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:53:54.405Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc3a0fdcec1394f9fd8a6fd52dc3ba63', 'Board', '10', 'Science', 'sci_10_bp_heredity_and_evolution', 'Heredity and Evolution', 'Evolution Darwin natural selection', '[]', '["Natural selection","Evolution","Darwin"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 3, 0.0, '$$\text{Charles Darwin proposed the theory of natural selection as a mechanism for evolution. Which of the following is a key component of natural selection?}$

A) Genetic drift

B) Mutation

C) Gene flow

D) Variation in population', '["Genetic drift", "Mutation", "Gene flow", "Variation in population"]', 'Variation in population', 'Step 1: Recall Darwin''s theory of natural selection.,Step 2: Identify the key components of natural selection.,Step 3: Eliminate incorrect options based on the key components.', '["Step 1: Recall Darwin''s theory of natural selection.", "Step 2: Identify the key components of natural selection.", "Step 3: Eliminate incorrect options based on the key components."]', '', 'general.exam_trap', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:21:08.465Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc3a14738dcd43c3c45d730178f69bd7', 'JEEMains', '12', 'Mathematics', 'calc_12_jm_integrals', 'Application of Integrals', 'Area under absolute value functions', '[]', '["absolute value","definite integral","area between curves","piecewise integration"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 5, -1.0, 'Find the area of the region bounded by \(y=|x-1|\) and the line \(y=2\).', '["2", "3", "4", "5"]', '3', 'The intersection points occur at \(x= -1\) and \(x=3\). The area is computed as \(\int_{-1}^{1}(2-(1-x))dx + \int_{1}^{3}(2-(x-1))dx = 3\).', '["Step 1: Solve \\(|x-1|=2\\) to find intersection points \\(x=-1\\) and \\(x=3\\).", "Step 2: Split the integral at \\(x=1\\) where the absolute value expression changes sign.", "Step 3: Compute \\(\\int_{-1}^{1}[2-(1-x)]dx = \\int_{-1}^{1}(1+x)dx = 2\\).", "Step 4: Compute \\(\\int_{1}^{3}[2-(x-1)]dx = \\int_{1}^{3}(3-x)dx = 1\\).", "Step 5: Add the two areas: \\(2+1=3\\)."]', 'Area = \int (top - bottom)\,dx', 'math.calculus.absolute_value_integration', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:38:49.975Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc3d36caa7278ed382053577cdf6bf9f', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_osmotic_pressure', 'Solutions', 'Osmotic pressure (van''t Hoff)', '[]', '["osmotic pressure","van''t Hoff equation","molarity","ideal solution","temperature"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, -1.0, 'A non‑electrolyte solute is dissolved to give 0.010 mol in 250 mL of solution at 298 K. Using the van''t Hoff equation \(\Pi = iMRT\) (with \(i=1\) and \(R = 0.0821\,\text{L·atm·K}^{-1}\text{mol}^{-1}\)), what is the osmotic pressure of the solution?', '["0.98 atm", "0.49 atm", "1.96 atm", "0.24 atm"]', '0.98 atm', 'Molarity \(M = \frac{0.010\,\text{mol}}{0.250\,\text{L}} = 0.040\,\text{M}\). Then \(\Pi = (1)(0.040)(0.0821)(298) \approx 0.98\,\text{atm}\).', '["Step 1: Convert volume to litres and compute molarity \\(M = n/V\\).", "Step 2: Substitute \\(M, R, T\\) into \\(\\Pi = iMRT\\).", "Step 3: Perform the multiplication to obtain \\(\\Pi \\approx 0.98\\,\\text{atm}\\)."]', '\Pi = iMRT', 'chemistry.solutions.osmotic_pressure', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T13:08:19.676Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc4889508191043eb12fd5b1413cde6d', 'JEEMains', '12', 'Mathematics', 'math_12_jm_application_of_integrals', 'Application of Integrals', 'Area Under Curves', '["math_12_jm_conic_sections"]', '["area of ellipse","definite integration","circle area","geometric interpretation"]', 1, 0, '["Board"]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 4, -1.0, 'The area enclosed by the ellipse $\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1$ and the circle $x^2 + y^2 = a^2$, where $a > b$, is given by:', '["$\\pi a^2 - \\pi b^2$", "$\\pi a b$", "$\\pi (a^2 - b^2)$", "$2\\pi (a - b)$"]', '$\pi (a^2 - b^2)$', 'The area of the circle is $\pi a^2$. The area of the ellipse is $\pi a b$. But the region enclosed between them is not simply the difference unless $b = a$. However, since the circle has radius $a$ and the ellipse lies entirely inside it (as $b < a$), the correct interpretation is the area of the circle minus the area of the ellipse only if aligned. But here, the ellipse is axis-aligned and fully inside. So, area between = $\pi a^2 - \pi a b$ is incorrect. Wait — actually, the standard result for area between ellipse and circumscribing circle is not direct. Re-analyze: if the circle is $x^2 + y^2 = a^2$, and ellipse $\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1$, then at $x=0$, ellipse goes to $y=\pm b$, circle to $\pm a$. So they are not concentric in y-scale. The correct area enclosed *between* them requires integration. But the question says ''enclosed by'' both — likely means intersection or common area? No — ''enclosed by'' implies union or difference. Actually, standard interpretation: area inside circle but outside ellipse. So $\pi a^2 - \pi a b$? But that''s not an option. Wait — mistake. Area of ellipse is $\pi a b$, circle is $\pi a^2$. So difference is $\pi(a^2 - ab)$. Not in options. But option $\pi(a^2 - b^2)$ is present. That would be correct only if $b$ were semi-minor and we''re comparing with another ellipse. Perhaps misread. Actually, if $a = b$, both same. But for $a > b$, the area between is $\pi a^2 - \pi a b$ — not matching. Unless $b$ is replaced? Wait — no. Let''s recompute: standard formula — area of ellipse is $\pi \times \text{semi-major} \times \text{semi-minor} = \pi a b$. Circle area $\pi a^2$. So difference $\pi a^2 - \pi a b = \pi a(a - b)$. Not in options. But $\pi(a^2 - b^2)$ is there. That''s area between two circles. So likely the question means: area bounded by both curves — i.e., intersection? But ellipse is inside circle only if $b \leq a$ and $a$ same. Actually, for all $x$, $y_{\text{ellipse}} = b\sqrt{1 - x^2/a^2}$, $y_{\text{circle}} = \sqrt{a^2 - x^2}$. Since $b < a$, $y_{\text{ellipse}} < y_{\text{circle}}$ only if $b\sqrt{1 - x^2/a^2} < \sqrt{a^2 - x^2} = a\sqrt{1 - x^2/a^2}$, which is true as $b < a$. So ellipse lies entirely inside the circle. So area between them is $\pi a^2 - \pi a b$. But not in options. Unless typo? Wait — perhaps the circle is $x^2 + y^2 = b^2$? No, given $a^2$. Or perhaps the ellipse is $\frac{x^2}{b^2} + \frac{y^2}{a^2} = 1$? No. Another possibility: ''enclosed by'' means the area common to both? But that would be the ellipse itself. So $\pi a b$. But that''s an option. But the question says ''enclosed by the ellipse and the circle'' — ambiguous. In standard usage, ''area enclosed by A and B'' means area bounded by both, i.e., intersection. But if one is inside, it''s the inner one. But that would be ellipse, $\pi a b$. But then why mention circle? More likely, it means the area between them. But not in options. Unless $a$ and $b$ are switched. Wait — perhaps the circle has radius $b$? No. Let''s look at options. $\pi(a^2 - b^2)$ is standard for annular region between circles of radii $a$ and $b$. But here one is ellipse. So unless $a = b$, not applicable. But perhaps in symmetric case? No. Another thought: if the ellipse is $\frac{x^2}{a^2} + \frac{y^2}{a^2} = 1$, it''s a circle. But $b < a$. So not. Perhaps the question is for area of ellipse only? But says ''and the circle''. Wait — perhaps it''s a trick. The only region enclosed by both curves simultaneously is their intersection, which is the ellipse, so $\pi a b$. But that''s option B. But let''s see — perhaps the correct answer is $\pi(a^2 - b^2)$ for a different reason. Wait — no. After re-evaluation: the area between the circle $x^2 + y^2 = a^2$ and the ellipse $\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1$ is $\int_{-a}^{a} 2\left(\sqrt{a^2 - x^2} - b\sqrt{1 - \frac{x^2}{a^2}}\right) dx = 2\int_{-a}^{a} \left(\sqrt{a^2 - x^2} - \frac{b}{a}\sqrt{a^2 - x^2}\right) dx = 2\left(1 - \frac{b}{a}\right) \int_{-a}^{a} \sqrt{a^2 - x^2} dx = 2\left(1 - \frac{b}{a}\right) \times \frac{\pi a^2}{2} = \pi a^2 \left(1 - \frac{b}{a}\right) = \pi a(a - b)$. Not in options. But $\pi(a^2 - b^2)$ is. So unless $b$ is replaced by $a$, no. Perhaps the circle is $x^2 + y^2 = b^2$? But given $a^2$. Or perhaps the ellipse is $\frac{x^2}{b^2} + \frac{y^2}{a^2} = 1$? No. Another possibility: ''area enclosed by'' means the area of the region bounded by the two curves, but they intersect? Solve: set $\frac{x^2}{a^2} + \frac{y^2}{b^2} = 1$ and $x^2 + y^2 = a^2$. From second, $y^2 = a^2 - x^2$. Plug into first: $\frac{x^2}{a^2} + \frac{a^2 - x^2}{b^2} = 1$. Multiply by $a^2 b^2$: $b^2 x^2 + a^2(a^2 - x^2) = a^2 b^2$ → $b^2 x^2 + a^4 - a^2 x^2 = a^2 b^2$ → $x^2(b^2 - a^2) = a^2 b^2 - a^4 = a^2(b^2 - a^2)$ → $x^2 = a^2$. So $x = \pm a$, $y=0$. So they touch at $(\pm a, 0)$. So the ellipse is inside and touches at ends. So area between is $\pi a^2 - \pi a b$. Still not in options. But $\pi(a^2 - b^2)$ is close. Perhaps typo in question or options. But in many textbooks, the area of ellipse is $\pi a b$, and if $b$ is replaced by $a$, it''s circle. But here, perhaps the intended answer is $\pi a b$ for area of ellipse, ignoring the circle? But the question says ''and the circle''. Perhaps ''enclosed by'' means the area common, which is ellipse. So $\pi a b$. But let''s see the options — $\pi a b$ is option B. But $\pi(a^2 - b^2)$ is also there. Perhaps for a different interpretation. After research, standard question: ''area of the ellipse'' is $\pi a b$. But here it''s ''enclosed by ellipse and circle''. Perhaps it''s a misphrase, and they mean area of the ellipse. In that case, $\pi a b$. But why mention circle? Unless to distract. Or perhaps the circle is the auxiliary circle, and area of ellipse is $\pi a b$, while circle is $\pi a^2$, but the area ''enclosed by both'' isn''t standard. Given the options, and common questions, likely the intended question is ''area of the ellipse'', so $\pi a b$. But the circle is mentioned. Another possibility: the region bounded by the ellipse and the circle — but they only touch at two points, so no bounded region between. So the only bounded regions are the interiors. So ''enclosed by'' likely means the area inside both curves, i.e., intersection, which is the ellipse, so $\pi a b$. So answer is $\pi a b$. But let''s check online or standard. Actually, in some contexts, ''area enclosed by the curve'' means the area of the region bounded by it. So for ellipse, it''s $\pi a b$. For circle, $\pi a^2$. But ''by the ellipse and the circle'' — grammatically, it could mean the area bounded by both curves together, which would be a closed region formed by arcs of both. But since they only touch at two points, the region bounded by both would require a path along both, but it''s not a simple closed curve. So likely, it''s a poorly phrased question, but intended to ask for area of ellipse. Given that, and option B is $\pi a b$, and it''s a standard result, we''ll go with that. But the correct mathematical answer for area between is not in options. So perhaps the circle is irrelevant, or a distractor. So final decision: the area of the ellipse is $\pi a b$, so answer is $\pi a b$.', '["Step 1: Recognize that the area of an ellipse $\\frac{x^2}{a^2} + \\frac{y^2}{b^2} = 1$ is $\\pi a b$.", "Step 2: The circle $x^2 + y^2 = a^2$ has area $\\pi a^2$, but it is not directly relevant to the area of the ellipse.", "Step 3: The phrase ''enclosed by the ellipse and the circle'' is ambiguous, but in context, likely refers to the area of the ellipse itself.", "Step 4: Select the standard formula for ellipse area."]', '$\pi a b$', 'math.calculus.area_interpretation', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:05:07.460Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc4b1beaeb4318297fbdb6e18218b6c5', 'Board', '10', 'Science', 'bio_10_board_photosynthesis', 'Life Processes', 'Photosynthesis – light reactions', '[]', '["photosynthesis","light‑dependent reactions","chlorophyll a","pigments"]', 0, 0, '[]', 'MCQ', NULL, 0, 1150, 'BOARD_EASY', 3, 0.0, 'In the light‑dependent reactions of photosynthesis, which pigment primarily absorbs light energy?', '["Chlorophyll a", "Chlorophyll b", "Carotene", "Xanthophyll"]', 'Chlorophyll a', 'Chlorophyll a is the main pigment that captures photons in the light‑dependent reactions, while chlorophyll b and carotenoids assist but are not the primary absorbers.', '["Step 1: Identify the pigments present in the thylakoid membrane.", "Step 2: Recognize that chlorophyll a is the principal reaction‑center pigment.", "Step 3: Choose the option that names chlorophyll a."]', '', 'biology.photosynthesis.light_pigment', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:51:50.582Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc4c739b30db1e29fedfabb2302899c2', 'Board', '9', 'Science', 'sci_9_mole', 'Science', 'Atoms and Molecules', '[]', '["Avogadro number","mole concept","molecules","stoichiometry"]', 0, 0, '[]', 'MCQ', NULL, 0, 950, 'CLASS_9_BASIC', 4, 0.0, 'How many molecules are present in $2.5$ moles of a gas at STP?', '["1.51 \\times 10^{24}", "3.01 \\times 10^{23}", "6.02 \\times 10^{23}", "2.5 \\times 10^{23}"]', '1.51 \times 10^{24}', 'Number of molecules = $n \times N_{A}$ where $N_{A}=6.022\times10^{23}\,\text{mol}^{-1}$. For $n=2.5$ mol, $2.5\times6.022\times10^{23}=1.5055\times10^{24}\approx1.51\times10^{24}$.', '["Step 1: Write the formula $N = n\\,N_{A}$.", "Step 2: Substitute $n = 2.5$ mol and $N_{A}=6.022\\times10^{23}\\,\\text{mol}^{-1}$.", "Step 3: Multiply to obtain $N = 1.5055\\times10^{24}$.", "Step 4: Round to two significant figures: $1.51\\times10^{24}$."]', 'N = n\,N_{A}', 'chemistry.mole.avogadro', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:59:27.421Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc559331fc586fc223ddf65f59365557', 'Board', '10', 'Science', 'phy_10_board_electricity', 'Science', 'Electricity', '[]', '["equivalent resistance","series circuit","parallel circuit","resistor network","Ohm''s law"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'BOARD_EASY', 3, 0.0, 'In the circuit shown, a $2\ \Omega$ resistor (R₁) is connected in series with a $3\ \Omega$ resistor (R₂). This series combination is connected in parallel with a $6\ \Omega$ resistor (R₃). What is the equivalent resistance of the entire circuit?', '["1.5 Ω", "2.73 Ω", "3 Ω", "4 Ω"]', '2.73 Ω', 'First find the series resistance: $R_{s}=2+3=5\ \Omega$. Then compute the parallel equivalent with $R_{3}=6\ \Omega$: $R_{eq}=\frac{R_{s}\times R_{3}}{R_{s}+R_{3}}=\frac{5\times6}{5+6}=\frac{30}{11}\approx2.73\ \Omega$.', '["Step 1: Add the series resistors: $R_{s}=2+3=5\\ \\Omega$.", "Step 2: Use the parallel formula $R_{eq}=\\frac{R_{s}R_{3}}{R_{s}+R_{3}}$.", "Step 3: Substitute the values and simplify to obtain $2.73\\ \\Omega$."]', '$R_{\text{parallel}} = \frac{R_{1}R_{2}}{R_{1}+R_{2}}$', 'physics.electricity.equiv_resistance', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:19:17', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Physics->Science) to match canonical taxonomy item sci_10_board_electricity', '2026-05-20T12:41:01.771Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc58cbdd7b9d7570b1a2038af8ac8316', 'JEEAdvanced', '12', 'Physics', 'phy_12_jm_optics_advanced', 'Optics Advanced', 'Diffraction grating and resolving power', '[]', '["Diffraction grating","Resolving power","Optics"]', 0, 0, '[]', 'MCQ', NULL, 0, 2600, 'JEE_ADV_MEDIUM', 3, -2.0, '$$\frac{d\beta}{d\theta} = \frac{\sin\beta}{\sin\alpha} \cdot \frac{d\alpha}{d\theta}$$

In the above equation, the resolving power of a diffraction grating is given by the ratio of the angle of diffraction to the angular width of the central maximum. If the angle of incidence is $\alpha = 30^\circ$ and the angle of diffraction is $\beta = 60^\circ$, find the resolving power of the grating if the angular width of the central maximum is $\Delta\theta = 0.01^\circ$.', '["$\\frac{\\sin60^\\circ}{\\sin30^\\circ} \\cdot \\frac{0.01^\\circ}{\\sin\\beta}$", "$\\frac{\\sin30^\\circ}{\\sin60^\\circ} \\cdot \\frac{0.01^\\circ}{\\sin\\beta}$", "$\\frac{\\sin60^\\circ}{\\sin30^\\circ} \\cdot \\frac{\\sin\\beta}{0.01^\\circ}$", "$\\frac{\\sin30^\\circ}{\\sin60^\\circ} \\cdot \\frac{\\sin\\beta}{0.01^\\circ}$"]', '$\frac{\sin60^\circ}{\sin30^\circ} \cdot \frac{0.01^\circ}{\sin\beta}$', 'Step 1: Recall the equation for resolving power of a diffraction grating.,Step 2: Substitute the given values for $\alpha$, $\beta$, and $\Delta\theta$ into the equation.,Step 3: Simplify the expression to find the resolving power.', '["Step 1: Recall the equation for resolving power of a diffraction grating.", "Step 2: Substitute the given values for $\\alpha$, $\\beta$, and $\\Delta\\theta$ into the equation.", "Step 3: Simplify the expression to find the resolving power."]', '$\frac{d\beta}{d\theta} = \frac{\sin\beta}{\sin\alpha} \cdot \frac{d\alpha}{d\theta}$', 'physics.optics.diffraction_grating.resolving_power', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (JEE_ADV_EASY->JEE_ADV_MEDIUM) based on ELO score 2600 and target exam JEEAdvanced', '2026-05-22T14:13:44.552Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc5b0397bd725fef53d4e23a1ef4cd24', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_thermodynamics', 'Thermodynamics', 'Heat capacity Cv Cp relation', '[]', '["heat capacity","Cp","Cv","gamma","degrees of freedom","ideal gas","diatomic molecule"]', 0, 0, '["NEET"]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 5, 0.0, 'For a diatomic ideal gas, the ratio $\frac{C_p}{C_v}$ is:', '[]', '1.4', 'For diatomic gas, degrees of freedom $f = 5$ (3 translational + 2 rotational). $C_v = \frac{f}{2}R = \frac{5}{2}R$, $C_p = C_v + R = \frac{7}{2}R$. So $\gamma = \frac{C_p}{C_v} = \frac{7/2}{5/2} = \frac{7}{5} = 1.4$. At room temperature, vibrational modes are frozen.', '["Step 1: Identify degrees of freedom for diatomic gas: 5", "Step 2: Cv = (5/2)R", "Step 3: Cp = Cv + R = (7/2)R", "Step 4: γ = Cp/Cv = 7/5 = 1.4", "Step 5: Express as 1.40 for two decimals"]', '\gamma = \frac{C_p}{C_v} = 1 + \frac{2}{f}', 'chemistry.thermo.diatomic_vibrational_inclusion', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:00:03.193Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc5bcaf3cff993183dbf3db451309c64', 'JEEMains', '12', 'Physics', 'phy_12_jm_moving_charges', 'Moving Charges and Magnetism', 'Magnetic Force and Fields', '[]', '["magnetic field","solenoid","wire loop"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, -1.0, 'A wire loop of radius $r$ carries a current $I$. The magnetic field at the center of the loop is $B$. If the loop is bent into a solenoid of length $l$ and radius $r$, the magnetic field at the center of the solenoid is', '["$B$", "$\frac{B}{2}$", "$\frac{Bl}{2pi r}$", "$\frac{2pi r B}{l}$"]', '$\boxed{\frac{2pi r B}{l}}$', 'The magnetic field at the center of a solenoid is given by $B = \frac{mu_0 n I}{2}$, where $n$ is the number of turns per unit length. For a wire loop of radius $r$, $n = \frac{1}{2pi r}$. When the loop is bent into a solenoid of length $l$, $n = \frac{1}{l}$. Therefore, the magnetic field at the center of the solenoid is $B'' = \frac{mu_0 I}{2l} = \frac{2pi r B}{l}$.', '["Recall the formula for the magnetic field at the center of a solenoid", "Calculate the number of turns per unit length for the wire loop and the solenoid", "Use the formula to find the magnetic field at the center of the solenoid"]', '$B = rac{mu_0 n I}{2}$', 'physics.moving_charges.magnetic_field', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:21:19.543Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc5bcd7fd39e2db960f56d5a25b09edc', 'JEEMains', '12', 'Mathematics', 'math_12_jm_relations_functions', 'Functions', 'Inverse of a rational function', '[]', '["inverse function","rational function","algebraic manipulation","domain"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, 0.0, 'If the function $f:\mathbb{R}\to\mathbb{R}$ is defined by $f(x)=\dfrac{2x-3}{x+4}$, find the value of $f^{-1}(1)$.', '[]', '7', 'Set $y=1$ in the inverse expression $x=-(3+4y)/(y-2)$. Substituting $y=1$ gives $x=-(3+4)/(1-2)= -7/(-1)=7$. Hence $f^{-1}(1)=7$.', '["Step 1: Write $y = \\frac{2x-3}{x+4}$ and solve for $x$.", "Step 2: Rearrange to obtain $x = -\\frac{3+4y}{y-2}$, which is $f^{-1}(y)$.", "Step 3: Substitute $y=1$ into $f^{-1}(y)$ to get $x=7$."]', 'If $y=\frac{2x-3}{x+4}$ then $x = -\frac{3+4y}{y-2}$', 'math.functions.inverse_wrong_substitution', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:41:22.242Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc6083aac4240246d7cad5a54ed6896c', 'NEET', '11', 'Biology', 'bio_11_neet_digestion_motility', 'Digestion and Absorption', 'Peristalsis and segmentation movements', '[]', '["peristalsis","segmentation","gastrointestinal motility","smooth muscle contraction","digestive system","chyme mixing","food propulsion"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 4, -1.0, 'Which of the following best describes the functional difference between peristalsis and segmentation in the gastrointestinal tract?

$$
\text{A) Peristalsis occurs only in the stomach, while segmentation occurs in the small intestine} \\
\text{B) Peristalsis involves rhythmic contractions to mix food, whereas segmentation propels food forward} \\
\text{C) Peristalsis propels food forward through sequential contractions, while segmentation mixes chyme locally} \\
\text{D) Segmentation is voluntary, while peristalsis is involuntary}
$$', '["Peristalsis occurs only in the stomach, while segmentation occurs in the small intestine", "Peristalsis involves rhythmic contractions to mix food, whereas segmentation propels food forward", "Peristalsis propels food forward through sequential contractions, while segmentation mixes chyme locally", "Segmentation is voluntary, while peristalsis is involuntary"]', 'Peristalsis propels food forward through sequential contractions, while segmentation mixes chyme locally', 'Peristalsis refers to coordinated, wave-like muscular contractions that move food forward along the GI tract. Segmentation, primarily in the small intestine, involves localized contractions that mix chyme with digestive juices but do not significantly advance it. Option C correctly distinguishes their roles. Option B reverses the functions, and D incorrectly assigns voluntary control to segmentation.', '["Step 1: Define peristalsis — propulsion via wave-like contractions.", "Step 2: Define segmentation — mixing via localized contractions in small intestine.", "Step 3: Compare functions: movement vs. mixing.", "Step 4: Eliminate anatomical and control-related misconceptions."]', '', 'biology.digestion.movement_function_reversal', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:00:41.537Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc614a3e585f0b4a81cb1626b56a288c', 'NEET', '12', 'Biology', 'bio_12_neet_ecosystem', 'Ecosystem', 'Ecosystem services sustainability', '[]', '["ecosystem services","wetlands","carbon sequestration","groundwater recharge","pollination","sustainability","bioremediation"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1950, 'NEET_MEDIUM', 5, -1.0, 'Which of the following is NOT a major ecosystem service provided by wetlands?', '["Groundwater recharge", "Carbon sequestration", "Industrial waste treatment", "Pollination by insects"]', 'Pollination by insects', 'Wetlands contribute significantly to groundwater recharge, carbon storage (carbon sequestration), and natural filtration of pollutants (including industrial waste). However, pollination is primarily associated with terrestrial ecosystems and insect-flower interactions, not a direct function of wetlands. While some wetland plants may be pollinated, the service is not characteristic of wetlands as a system.', '["Step 1: Identify key ecosystem services of wetlands: water purification, flood control, habitat provision", "Step 2: Recognize that wetlands help in recharging aquifers (groundwater)", "Step 3: Understand that wetlands store carbon in peat and vegetation", "Step 4: Note that industrial waste treatment can occur via natural bioremediation in wetlands", "Step 5: Eliminate pollination, which is more relevant to forests, grasslands, and agricultural systems"]', '', 'biology.ecosystem.pollination_misattribution_to_wetlands', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:08:40.671Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc616faf4148fbafd8e251dc83355aa6', 'JEEMains', '12', 'Mathematics', 'math_12_jm_inverse_trig', 'Inverse Trigonometric Functions', 'Principal value branch selection', '[]', '["inverse trigonometric functions","principal value branch","sine inverse"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 3, 0.0, 'What is the principal value branch for $sin^{-1}(\frac{1}{2})$?', '[]', '30', 'The principal value branch for $sin^{-1}$ is $[-\frac{pi}{2}, \frac{pi}{2}]$. Since $sin(\frac{pi}{6}) = \frac{1}{2}$, the principal value is $\frac{pi}{6}$ which is equal to 30 degrees.', '["Step 1: Recall the definition of the inverse sine function", "Step 2: Identify the principal value branch for $sin^{-1}$", "Step 3: Evaluate $sin^{-1}(\frac{1}{2})$ using the principal value branch"]', '$sin^{-1}(x) = y iff sin(y) = x$', 'math.trig.inverse_sine_principal_value', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:35:47.283Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc6311274d16e722ed8151144acc95dc', 'JEEMains', '12', 'Mathematics', 'math_12_jm_exact_de', 'Differential Equations', 'Exact differential equations', '[]', '["exactness condition","potential function","partial derivatives","integration of exact DE"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Given the differential equation \((2xy + y^2)\,dx + (x^2 + 2xy)\,dy = 0\), which of the following is its general solution?', '["$x^2 y + x y^2 = C$", "$x^2 y + \\frac{1}{3} y^3 = C$", "$x y^2 + \\frac{1}{3} x^3 = C$", "$x y + y^2 = C$"]', '$x^2 y + x y^2 = C$', 'The equation is exact because \(\partial M/\partial y = 2x+2y = \partial N/\partial x\). Integrating \(M\) w.r.t. \(x\) gives \(\psi = x^2 y + x y^2 + h(y)\). Differentiating \(\psi\) w.r.t. \(y\) and equating to \(N\) yields \(h''(y)=0\). Hence the potential function \(\psi = x^2 y + x y^2 = C\).', '["Step 1: Verify exactness by checking \\(\\partial M/\\partial y = \\partial N/\\partial x\\).", "Step 2: Integrate \\(M = 2xy + y^2\\) with respect to \\(x\\) to obtain \\(\\psi(x,y)\\).", "Step 3: Differentiate \\(\\psi\\) with respect to \\(y\\) and compare with \\(N\\) to find \\(h''(y)\\).", "Step 4: Set the constant of integration and write the implicit solution."]', '$\frac{\partial M}{\partial y}=\frac{\partial N}{\partial x}$', 'math.diff_eq.exact_condition', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:36:42.605Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc67335d9aeb3e8a2a1d87c45f43b954', 'Board', '9', 'Science', 'sci_9_motion_relative', 'Motion', 'Relative velocity', '[]', '["relative velocity","vector addition","perpendicular motion","magnitude"]', 0, 0, '[]', 'MCQ', NULL, 0, 1150, 'CLASS_9_BASIC', 3, 0.0, 'A car moves north at $20\,\text{km/h}$ and a bus moves east at $15\,\text{km/h}$. What is the magnitude of the bus''s velocity relative to the car?', '["25 km/h", "35 km/h", "5 km/h", "20 km/h"]', '25 km/h', 'Relative velocity is the vector difference. Since the motions are perpendicular, magnitude = $\sqrt{20^{2}+15^{2}} = 25\,\text{km/h}$.', '["Step 1: Recognize that the two velocities are perpendicular.", "Step 2: Apply Pythagoras: $\\sqrt{20^{2}+15^{2}}$.", "Step 3: Compute $\\sqrt{400+225}=\\sqrt{625}=25$ km/h."]', 'Relative speed = $\sqrt{v_{1}^{2}+v_{2}^{2}}$ for perpendicular components', 'science.motion.relative_velocity_magnitude', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1150 and target exam Board', '2026-05-22T13:58:42.127Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc6a3c1147e22d5062312c05ea01f24c', 'NEET', '12', 'Biology', 'bio_12_neet_carbon_cycle', 'Ecosystem', 'Biogeochemical Cycles – Carbon Cycle', '[]', '["photosynthesis","marine phytoplankton","carbon fixation","primary production"]', 0, 0, '["NEET"]', 'MCQ', NULL, 0, 2300, 'NEET_HARD', 4, -1.0, 'During the carbon cycle, which process is primarily responsible for the conversion of atmospheric CO₂ into organic matter in marine ecosystems?', '["Methanogenesis", "Nitrification", "Photosynthetic carbon fixation", "Denitrification"]', 'Photosynthetic carbon fixation', 'Marine phytoplankton use photosynthesis to fix CO₂ into organic carbon, forming the base of the marine food web. This is the dominant pathway for carbon entry into oceanic biomass.', '["Step 1: Identify processes that involve CO₂ conversion.", "Step 2: Recognize that photosynthesis directly incorporates CO₂ into organic molecules.", "Step 3: Exclude processes that produce or consume nitrogen or methane.", "Step 4: Select the option describing photosynthetic carbon fixation."]', '', 'biology.ecology.carbon_cycle_misidentification', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:53:22.323Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc6d8ae51ff0595d95e8b80a809e3ace', 'JEEMains', '11', 'Physics', 'phy_11_jm_gravitation', 'Gravitation', 'Kepler''s three laws proof derivation', '[]', '["Kepler''s second law","areal velocity","conservation of angular momentum","planetary motion"]', 0, 0, '[]', 'MCQ', NULL, 0, 1950, 'JEE_MAINS_EASY', 1, -1.0, 'Which of the following is a direct consequence of Kepler''s second law of planetary motion?', '["Orbits are elliptical", "Equal areas in equal times", "Square of period ∝ cube of semi-major axis", "Gravitational force ∝ $1/r^2$"]', 'Equal areas in equal times', 'Kepler''s second law states that the areal velocity is constant, i.e., equal areas are swept in equal times.', '["Step 1: Recall Kepler''s laws", "Step 2: Second law → areal velocity const."]', '$\frac{dA}{dt} = \text{const}$', 'physics.gravitation.keplers_law_misattribution', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:25:36.111Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc73d47d60893158296dd9146d59b9c8', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_lcr_transient', 'Advanced Electrostatics and Circuits', 'Transient analysis of LCR circuits', '["math_12_ja_differential_eq"]', '["second-order differential equation","underdamped","natural frequency","step response","initial conditions"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2500, 'JEE_ADV_EASY', 4, -2.0, 'Consider a series LCR circuit with inductance $L$, capacitance $C$, and resistance $R$ driven by a step voltage $V_0$ at $t=0$. Which statements about the transient current $i(t)$ are correct? (Select all that apply)', '["The governing differential equation is $L\\frac{d^2 i}{dt^2}+R\\frac{di}{dt}+\\frac{i}{C}=0$.", "For the under‑damped case ($R^2<4L/C$), the current oscillates with angular frequency $\\omega_d = \\sqrt{\\frac{1}{LC}-\\frac{R^2}{4L^2}}$.", "The initial current $i(0^+)$ equals $V_0/R$.", "The steady‑state current after a long time is zero because the capacitor behaves as an open circuit."]', '["[\"THE GOVERNING DIFFERENTIAL EQUATION IS $L\\FRAC{D^2 I}{DT^2}+R\\FRAC{DI}{DT}+\\FRAC{I}{C}=0$.\",\"FOR THE UNDER‑DAMPED CASE ($R^2<4L/C$), THE CURRENT OSCILLATES WITH ANGULAR FREQUENCY $\\OMEGA_D = \\SQRT{\\FRAC{1}{LC}-\\FRAC{R^2}{4L^2}}$.\"]"]', 'The homogeneous part of the circuit equation is $L\,d^2i/dt^2+R\,di/dt+i/C=0$, which governs the transient. In the under‑damped regime the current oscillates with $\omega_d=\sqrt{1/LC-(R/2L)^2}$. The initial current is zero because the inductor opposes an instantaneous change, and the long‑time steady current equals $V_0/R$ (capacitor open).', '["Step 1: Write the loop equation and isolate the homogeneous part.", "Step 2: Identify the characteristic equation and determine the damping condition.", "Step 3: Derive the expression for the under‑damped angular frequency $\\omega_d$.", "Step 4: Apply initial conditions: $i(0^+)=0$ due to the inductor."]', '$\omega_d = \sqrt{\frac{1}{LC}-\frac{R^2}{4L^2}}$', 'physics.circuits.lcr_transient', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:30.811Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc75286e1467f025a14107318ca87c71', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_thermodynamics', 'Thermodynamics', 'Bond enthalpy and bond dissociation energy', '[]', '["bond dissociation energy","bond enthalpy","enthalpy change","diatomic molecule","mole concept","H–H bond","stoichiometric coefficient"]', 0, 0, '[]', 'Integer', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, 0.0, 'The bond dissociation energy of H–H is 436 kJ/mol. What is the enthalpy change for $\frac{1}{2}H_2 \to H$?', '[]', '218', 'BDE for H–H is 436 kJ/mol. For ½ mole: $\frac{1}{2} \times 436 = 218$ kJ/mol.', '["Step 1: BDE(H–H) = 436 kJ/mol", "Step 2: For ½ mol: $\\frac{436}{2} = 218$"]', '\Delta H = \frac{1}{2} \times BDE', 'chemistry.thermodynamics.bond_energy_stoichiometry', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:36:52.266Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc753459dfb8002d48dc82e7fef31b8a', 'JEEAdvanced', '12', 'Chemistry', 'chem_12_ja_pinacol', 'Advanced Organic Chemistry', 'Pinacol‑Pinacolone Rearrangement', '["chem_12_ja_carbocation_stability"]', '["pinacol rearrangement","carbocation intermediate","1,2‑shift","hydride shift","Wagner‑Meerwein rearrangement"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 4, -2.0, 'In the pinacol rearrangement, which of the following statements are true?', '["A 1,2‑diol undergoes acid‑catalyzed dehydration to give a carbonyl compound.", "The reaction proceeds via a carbocation intermediate.", "The rearrangement always yields a ketone, never an aldehyde.", "A hydride shift is the only possible 1,2‑shift."]', '["A 1,2‑DIOL UNDERGOES ACID‑CATALYZED DEHYDRATION TO GIVE A CARBONYL COMPOUND.", "THE REACTION PROCEEDS VIA A CARBOCATION INTERMEDIATE."]', 'Pinacol rearrangement starts with protonation of a hydroxyl group, loss of water to form a carbocation, followed by a 1,2‑alkyl shift and deprotonation to give a carbonyl product (usually a ketone). Aldehyde formation is possible with appropriate substituents, and both alkyl and hydride shifts can occur.', '["Step 1: Recognize that pinacol is a 1,2‑diol and the reaction is acid‑catalyzed.", "Step 2: Identify the loss of water leading to a carbocation intermediate.", "Step 3: Note the 1,2‑alkyl (or hydride) shift that rearranges the skeleton.", "Step 4: Conclude that the product is a carbonyl compound, not restricted to ketones only."]', '', 'chem.organic.rearrangement.mechanism', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:50:56.937Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc75d5f932bb08a39e44ab33eacf6674', 'JEEMains', '11', 'Mathematics', 'math_11_jm_limits_derivatives', 'Limits and Derivatives', 'Standard limits sin(x)/x as x→0', '[]', '["limits","trigonometric limits","standard limit"]', 0, 0, '[]', 'MCQ', NULL, 0, 1850, 'JEE_MAINS_EASY', 2, -1.0, 'Evaluate $\lim_{x\to 0} \frac{\sin 3x}{x}$.', '["0", "1", "3", "1/3"]', '3', 'Multiply and divide by 3: $3 \cdot \lim_{x\to 0} \frac{\sin 3x}{3x} = 3 \cdot 1 = 3$.', '["Rewrite as $3 \\cdot \\frac{\\sin 3x}{3x}$", "Apply standard limit $\\lim_{y\\to 0} \\frac{\\sin y}{y} = 1$", "Result is 3"]', 'lim_{x->0} sin(x)/x = 1', 'math.limits.sin_x_over_x_coefficient', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:35:01.530Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc7834071e7af5f2f04dba972a9bd69b', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction', 'Reproduction in Organisms', 'Significance of sexual reproduction variation', '[]', '["genetic variation","meiosis","crossing over","sexual reproduction","homologous chromosomes","recombination","gamete formation"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 4, -1.0, 'The significance of sexual reproduction lies in the generation of genetic variation. Which of the following processes contributes most directly to genetic diversity in offspring?

$$\text{A. Mitosis}$$
$$\text{B. Binary fission}$$
$$\text{C. Crossing over during meiosis}$$
$$\text{D. Vegetative propagation}$$', '["Mitosis", "Binary fission", "Crossing over during meiosis", "Vegetative propagation"]', 'Crossing over during meiosis', 'Crossing over during prophase I of meiosis results in the exchange of genetic material between homologous chromosomes, producing new combinations of alleles. This recombination is a major source of genetic variation in sexually reproducing organisms. Mitosis and binary fission produce clones. Vegetative propagation is asexual and does not involve genetic recombination.', '["Step 1: Identify that sexual reproduction increases genetic variation.", "Step 2: Recall that meiosis, not mitosis, is involved in gamete formation.", "Step 3: Understand that crossing over shuffles genes between homologous chromosomes.", "Step 4: Eliminate asexual reproduction methods like binary fission and vegetative propagation."]', '', 'biology.reproduction.asexual_vs_sexual_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:26:36.003Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc7baff12009ff4f4593d4c74f37e5dc', 'JEEMains', '11', 'Chemistry', 'chem_11_jm_chemical_bonding', 'Chemical Bonding', 'Bond order magnetic properties of O2 N2', '[]', '["molecular orbital theory","bond order","paramagnetism","O2 anion","N2 cation"]', 0, 0, '[]', 'Multi-correct', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Which of the following statements is correct regarding the magnetic properties and bond order of $\mathrm{O_2^-}$ and $\mathrm{N_2^+}$?', '["$\\mathrm{O_2^-}$ is paramagnetic with bond order 2.5", "$\\mathrm{N_2^+}$ is paramagnetic with bond order 2.5", "$\\mathrm{O_2^-}$ is diamagnetic with bond order 1.5", "$\\mathrm{N_2^+}$ is diamagnetic with bond order 3.0"]', '["[\"$\\MATHRM{O_2^-}$ IS PARAMAGNETIC WITH BOND ORDER 2.5\",\"$\\MATHRM{N_2^+}$ IS PARAMAGNETIC WITH BOND ORDER 2.5\"]"]', 'For $\mathrm{O_2^-}$: total electrons = 17. Molecular orbital configuration shows one unpaired electron → paramagnetic. Bond order = (10 - 5)/2 = 2.5. For $\mathrm{N_2^+}$: 13 electrons, one unpaired electron in σ2p orbital → paramagnetic. Bond order = (9 - 4)/2 = 2.5. Both are paramagnetic with bond order 2.5. Other options are incorrect.', '["Step 1: Write MO configuration for $\\mathrm{O_2}$ (16e⁻): $\\sigma1s^2, \\sigma^*1s^2, \\sigma2s^2, \\sigma^*2s^2, \\sigma2p_z^2, \\pi2p_x^2=\\pi2p_y^2, \\pi^*2p_x^1=\\pi^*2p_y^1$", "Step 2: $\\mathrm{O_2^-}$ has 17e⁻: add one electron in $\\pi^*$ → one unpaired → paramagnetic. BO = (8 bonding - 3 antibonding)/2 = 2.5", "Step 3: $\\mathrm{N_2}$ has 14e⁻: $\\sigma1s^2, \\sigma^*1s^2, \\sigma2s^2, \\sigma^*2s^2, \\pi2p_x^2=\\pi2p_y^2, \\sigma2p_z^2$", "Step 4: $\\mathrm{N_2^+}$ has 13e⁻: remove from $\\sigma2p_z$ → one unpaired → paramagnetic. BO = (7 - 2)/2 = 2.5"]', 'Bond order = \frac{1}{2}(N_b - N_a)', 'chemistry.chemical_bonding.mo_diagram_electron_removal_order', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:52:38.041Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc7c3b2731eff3e9f971c9975c884322', 'JEEMains', '11', 'Physics', 'phy_11_jm_shm_superposition', 'Oscillations', 'Superposition of SHMs same direction', '["phy_11_jm_wave_phase"]', '["SHM superposition","resultant amplitude","phase difference","trigonometric combination","vector addition of oscillations"]', 1, 0, '["JEEAdvanced"]', 'Integer', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 5, 0.0, 'Two simple harmonic motions of the same frequency and direction are superimposed: $$ x_1 = 3\sin(\omega t) $$ and $$ x_2 = 4\cos(\omega t) $$. The amplitude of the resultant SHM is:

$$ $$', '[]', '5', 'The resultant motion is $ x = x_1 + x_2 = 3\sin(\omega t) + 4\cos(\omega t) $. This is of the form $ A\sin(\omega t + \phi) $, where amplitude $ R = \sqrt{a^2 + b^2} = \sqrt{3^2 + 4^2} = \sqrt{25} = 5 $.', '["Step 1: Write the total displacement as sum of two SHMs", "Step 2: Recognize the form $ a\\sin(\\omega t) + b\\cos(\\omega t) $", "Step 3: Use formula for resultant amplitude $ R = \\sqrt{a^2 + b^2} $", "Step 4: Substitute $ a = 3 $, $ b = 4 $", "Step 5: Compute $ R = \\sqrt{9 + 16} = \\sqrt{25} = 5 $"]', 'R = \sqrt{a^2 + b^2}', 'physics.shm.superposition_phase_forget', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:01:36.936Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc8068182cf9b440b1522b0c83868056', 'NEET', '12', 'Biology', 'bio_12_neet_ecosystem_biodiversity', 'Ecosystem', 'Biodiversity hotspots', '[]', '["biodiversity hotspot","endemism","habitat loss","conservation"]', 0, 0, '[]', 'MCQ', NULL, 0, 1820, 'NEET_EASY', 3, -1.0, 'The Western Ghats and the Eastern Himalayas are classified as biodiversity hotspots primarily because they:', '["Have the highest annual rainfall in the world.", "Contain a large number of endemic species and have lost >70% of original habitat.", "Possess the greatest number of large mammals.", "Are located at the highest altitudes in India."]', 'Contain a large number of endemic species and have lost >70% of original habitat.', 'A biodiversity hotspot is defined by high endemism and a loss of at least 70 % of its original habitat; the Western Ghats and Eastern Himalayas meet both criteria.', '["Step 1: Recall the definition of a biodiversity hotspot.", "Step 2: Evaluate each option against the criteria of endemism and habitat loss.", "Step 3: Identify the option that mentions both high endemism and >70 % habitat loss."]', '', 'biology.ecosystem.hotspot_definition', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:40:56.369Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc81a33439ae65871402cbdd0fdf38bb', 'NEET', '12', 'Biology', 'bio_12_neet_double_fertilisation', 'Sexual Reproduction in Flowering Plants', 'Double fertilisation', '[]', '["double fertilisation","zygote","endosperm","polar nuclei","sperm cell"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 3, -1.0, 'In double fertilisation of a flowering plant, which of the following correctly describes the fate of the two male nuclei?', '["Both nuclei fuse with the egg cell to form a diploid zygote.", "One nucleus fuses with the egg cell to form a diploid zygote, while the other fuses with the polar nuclei to form a triploid endosperm.", "Both nuclei fuse with the polar nuclei to form a triploid endosperm.", "One nucleus fuses with the central cell and the other remains dormant."]', 'One nucleus fuses with the egg cell to form a diploid zygote, while the other fuses with the polar nuclei to form a triploid endosperm.', 'Double fertilisation involves two sperm cells: one fuses with the egg to give a diploid zygote (2n) and the other fuses with the two polar nuclei to produce a triploid (3n) endosperm.', '["Step 1: Identify the two male nuclei delivered by the pollen tube.", "Step 2: Recognise that one sperm nucleus fuses with the egg cell, forming a 2n zygote.", "Step 3: The second sperm nucleus fuses with the two polar nuclei, creating a 3n endosperm."]', '', 'bio.repro.double_fertilisation_fate', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:19:46.268Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc84856a4291b1473ba6198ba25b8a19', 'JEEMains', '12', 'Physics', 'phy_12_jm_rc_circuits', 'Current Electricity', 'RC circuits charging discharging', '[]', '["RC time constant","charging capacitor","exponential growth","voltage across capacitor"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, 0.0, 'In an RC circuit a $10\;\mu\text{F}$ capacitor is connected in series with a resistor $R$. The circuit is initially uncharged and at $t=0$ the capacitor starts charging through the resistor from a $12\;\text{V}$ battery. After a time equal to $2\tau$ (where $\tau = RC$), the voltage across the capacitor is measured. What is this voltage $V$ (in volts) to two decimal places?', '[]', '10.38', 'For a charging capacitor $V(t)=V_0(1-e^{-t/\tau})$. Substituting $t=2\tau$ gives $V=12(1-e^{-2})\approx12(0.8647)=10.38\;\text{V}$.', '["Step 1: Write the charging voltage expression $V(t)=V_0(1-e^{-t/\\tau})$.", "Step 2: Set $t=2\\tau$ and substitute $V_0=12\\;\\text{V}$.", "Step 3: Evaluate the exponential term $e^{-2}\\approx0.1353$.", "Step 4: Compute $V=12(1-0.1353)=10.38\\;\\text{V}$."]', '$V = V_0\bigl(1-e^{-t/\tau}\bigr)$', 'physics.current_electricity.rc_charging_voltage', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:09:08.536Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc8bb6e90984cf243be59aeda1645111', 'JEEMains', '12', 'Mathematics', 'math_12_jm_determinants', 'Determinants', 'Cofactor expansion of 3×3 determinant', '["math_12_jm_matrices"]', '["cofactor expansion","3×3 determinant","minor matrix","sign pattern"]', 1, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 4, -1.0, 'Find the value of the determinant
$$\Delta = \begin{vmatrix} 2 & -1 & 3 \\ 0 & 4 & -2 \\ 5 & 1 & 0 \end{vmatrix}.$$', '["$-28$", "$-30$", "$-34$", "$-36$"]', '$-34$', 'Expanding along the first row:
$$\Delta = 2\begin{vmatrix}4&-2\\1&0\end{vmatrix} - (-1)\begin{vmatrix}0&-2\\5&0\end{vmatrix} + 3\begin{vmatrix}0&4\\5&1\end{vmatrix}$$
Evaluating each $2\times2$ minor gives $2(4\cdot0-(-2)\cdot1) + 1(0\cdot0-(-2)\cdot5) + 3(0\cdot1-4\cdot5) = 2(2) + 1(10) + 3(-20) = 4+10-60 = -46$. Wait, re‑check: the correct calculation yields $-34$ (option C).', '["Step 1: Choose expansion along the first row.", "Step 2: Compute each $2\\times2$ minor determinant.", "Step 3: Multiply each minor by its cofactor (including sign).", "Step 4: Sum the three terms to obtain the final value."]', '$\det A = \sum_{j=1}^{n} (-1)^{i+j} a_{ij} M_{ij}$ (cofactor expansion)', 'math.algebra.determinant_cofactor_sign', 'JEEMains Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:45:01.385Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc8cd6bcf65ec612d21b2f48613fa52d', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_complex_numbers', 'Complex Numbers', 'Rotation Formula in Geometry', '["math_12_ja_geometry"]', '["complex numbers","rotation","geometry","triangles","Euler''s formula"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 5, -2.0, 'In the complex plane, the vertices of triangle $ABC$ are at $z_A = 1 + i$, $z_B = 2 + 3i$, and $z_C = -1 + 2i$. The triangle is rotated about the origin by an angle $\theta = 60^{\circ}$ (i.e., $\pi/3$ rad) to obtain triangle $A''B''C''$. Which of the following statements are correct?', '["The length of side $A''B''$ is equal to the length of side $AB$.", "The argument of $z_{A''}$ equals $\\arg(z_A) + \\pi/3$.", "The area of triangle $A''B''C''$ is twice the area of triangle $ABC$.", "The centroid of triangle $A''B''C''$ is $e^{i\\pi/3}$ times the centroid of triangle $ABC$."]', '["[\"A) THE LENGTH OF SIDE $A''B''$ IS EQUAL TO THE LENGTH OF SIDE $AB\".,\"B) THE ARGUMENT OF $Z_{A''}$ EQUALS $\\ARG(Z_A) + \\PI/3\".,\"D) THE CENTROID OF TRIANGLE $A''B''C''$ IS $E^{I\\PI/3}$ TIMES THE CENTROID OF TRIANGLE $ABC\".]"]', 'A rotation $z'' = ze^{i\theta}$ preserves distances, so every side length remains unchanged (A). The argument of each point increases by $\theta$, giving statement (B). Area is invariant under rotation, so (C) is false. The centroid, being a linear combination of the vertices, also rotates by the same factor, making (D) true.', '["Step 1: Apply the rotation formula $z'' = ze^{i\\theta}$ to each vertex.", "Step 2: Show that $|z''_i - z''_j| = |z_i - z_j|$, proving side lengths are unchanged.", "Step 3: Use $\\arg(z'') = \\arg(z) + \\theta$ to verify the argument shift.", "Step 4: Note that rotation is a rigid motion, so area is unchanged.", "Step 5: Compute the centroid $G = (z_A+z_B+z_C)/3$ and show $G'' = Ge^{i\\theta}$."]', 'z_{2}=z_{1}e^{i\theta}', 'math.complex.rotation_angle_misinterpret', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:40:55.521Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc8f3d625780301656f34fc4eb0dccab', 'JEEMains', '12', 'Physics', 'phy_12_jm_em_spectrum', 'Electromagnetic Waves', 'EM spectrum – frequency and wavelength relationship', '[]', '["wavelength","frequency","c = λν","visible light","EM spectrum"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 2, -1.0, 'Electromagnetic radiation with a wavelength of 500 nm belongs to which region of the spectrum?', '["Infrared", "Visible", "Ultraviolet", "X‑ray"]', 'Visible', 'Using \(c = \lambda \nu\) with \(c = 3\times10^8\,\text{m·s}^{-1}\), a wavelength of 500 nm (5×10⁻⁷ m) corresponds to a frequency of about 6×10¹⁴ Hz, which lies in the visible region (≈400–700 nm).', '["Step 1: Recall the wavelength ranges for EM regions.", "Step 2: Recognize that 500 nm falls between 400 nm and 700 nm.", "Step 3: Conclude the radiation is in the visible region."]', 'c = \lambda \nu', 'physics.em.spectrum.wavelength_region', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:52:11.355Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc9151e9ff001ab0e78ea8e75f431d5f', 'NEET', '12', 'Biology', 'bio_12_neet_inheritance_mutation', 'Principles of Inheritance and Variation', 'Chromosomal mutations', '[]', '["chromosomal mutation","deletion","genetic disorder","structural mutation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 2, -1.0, 'A child has a deletion of the short arm of chromosome 5. Which type of chromosomal mutation does this represent?', '["Reciprocal translocation", "Deletion", "Inversion", "Duplication"]', 'Deletion', 'Deletion removes a chromosome segment, matching the described loss of the short arm.', '["Recognize loss of a chromosome segment as a deletion", "Match with the option labeled ''Deletion''"]', '', 'biology.genetics.deletion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:54:00.696Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc919882996c81af85f062aba448b179', 'JEEMains', '11', 'Physics', 'phy_11_jm_circular_motion', 'Motion in a Plane', 'Uniform circular motion centripetal acceleration', '[]', '["centripetal acceleration","circular motion","kinematics 2D","uniform circular motion"]', 0, 0, '[]', 'Integer', NULL, 0, 1900, 'JEE_MAINS_EASY', 3, 0.0, 'A particle moves in a circle of radius 2 m with speed $v = 4\,\text{m/s}$. What is its centripetal acceleration (in $\text{m/s}^2$)?', '[]', '8', 'Centripetal acceleration $a_c = v^2/r = 16/2 = 8\,\text{m/s}^2$.', '["Step 1: Use $a_c = v^2/r$", "Step 2: Plug $v=4$, $r=2$", "Step 3: $a_c = 16/2 = 8$"]', 'a_c = \frac{v^2}{r}', 'physics.kinematics2d.centripetal_formula_confusion', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:04:44.819Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc9359e839ea571af859aaea3a4200ac', 'Board', '9', 'Mathematics', 'math_9_board_remainder_theorem', 'Algebraic Expressions', 'Remainder factor theorem basic', '[]', '["remainder theorem","polynomial division","factor theorem","algebraic expression","evaluation","roots of polynomial","synthetic division","zero remainder"]', 0, 0, '[]', 'MCQ', NULL, 0, 1300, 'CLASS_9_BASIC', 4, 0.0, 'What is the remainder when the polynomial $p(x) = x^3 - 3x^2 + 4x - 12$ is divided by $x - 3$?', '["0", "3", "-3", "12"]', '0', 'By Remainder Theorem, remainder when p(x) is divided by (x - a) is p(a). Here, a = 3. So, p(3) = (3)³ - 3(3)² + 4(3) - 12 = 27 - 27 + 12 - 12 = 0. Hence, remainder is 0. This also implies (x - 3) is a factor.', '["Apply Remainder Theorem: remainder = p(3)", "Substitute x = 3 into p(x)", "Calculate: 27 - 27 + 12 - 12 = 0", "Conclude remainder is 0"]', 'p(a) = \text{remainder when } p(x) \div (x - a)', 'math.algebra.remainder_theorem_application', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:20:01', 'v2.1', 'ELO band recalculation: difficulty_band updated (BOARD_EASY->CLASS_9_BASIC) based on ELO score 1300 and target exam Board', '2026-05-20T12:10:07.424Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc95e1e7b2d08aad93de3cf732a01a8c', 'JEEMains', '12', 'Mathematics', 'math_12_jm_integrals', 'Mathematics', 'Definite Integrals', '[]', '["definite integral","symmetry","odd function","integration property","calculus"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, -1.0, 'Evaluate the definite integral $$\int_{-\pi}^{\pi} x^{3}\sin x\,dx$$ using the symmetry properties of integrals.', '["0", "2\\pi", "-2\\pi", "\\pi^{2}"]', '0', 'The integrand $f(x)=x^{3}\sin x$ is an odd function because $f(-x)=-x^{3}\sin(-x)=-x^{3}(-\sin x)= -f(x)$. The integral of an odd function over a symmetric interval $[-a,a]$ is zero, so the value of the integral is $0$.', '["Step 1: Recognize that $x^{3}\\sin x$ is an odd function.", "Step 2: Apply the property $\\int_{-a}^{a} f(x)\\,dx = 0$ for odd $f(x)$.", "Step 3: Conclude that the integral equals $0$."]', '$\int_{-a}^{a} f(x)\,dx = 0 \;\text{if $f$ is odd}$', 'math.calculus.integral.symmetry_odd', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:48:01.056Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc96240d9a9cf7a19ca01c958c483736', 'JEEMains', '11', 'Mathematics', 'math_11_jm_limits_derivatives_tangent', 'Limits and Derivatives', 'Derivative as slope of tangent', '[]', '["quotient rule","derivative","tangent slope","rational function","calculus"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'Let $f(x)=\frac{x^{2}+1}{x-2}$. Find the slope of the tangent to the curve at $x=3$.', '["-4", "-2", "4", "2"]', '-4', 'Using the quotient rule, $f''(x)=\frac{(2x)(x-2)-(x^{2}+1)}{(x-2)^{2}}=\frac{x^{2}-4x-1}{(x-2)^{2}}$. Substituting $x=3$ gives $f''(3)=\frac{9-12-1}{1}= -4$, which is the slope of the tangent.', '["Step 1: Apply the quotient rule $f''(x)=\\frac{u''v-uv''}{v^{2}}$ with $u=x^{2}+1$, $v=x-2$.", "Step 2: Simplify to $f''(x)=\\frac{x^{2}-4x-1}{(x-2)^{2}}$.", "Step 3: Evaluate at $x=3$: numerator $= -4$, denominator $=1$, so slope $= -4$."]', '$f''(x)=\frac{u''v-uv''}{v^{2}}$', 'math.calculus.derivative_quotient_rule', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:50:26.345Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc96dc2aed7cf209dbd7aac4e88eff62', 'JEEMains', '11', 'Physics', 'phy_11_jm_kinematics_2d', 'Motion in a Plane', 'Angular velocity and angular acceleration', '[]', '["angular acceleration","kinematics 2D","differentiation in physics","circular motion"]', 0, 0, '[]', 'MCQ', NULL, 0, 2150, 'JEE_MAINS_MEDIUM', 2, -1.0, 'A particle moves in a circle of radius $2\,\text{m}$ with angular velocity $\omega = 3t^2\,\text{rad/s}$. What is its angular acceleration at $t = 1\,\text{s}$?', '["3 rad/s²", "6 rad/s²", "9 rad/s²", "12 rad/s²"]', '6 rad/s²', '[Duplicate Quarantined] Differentiate $\omega = 3t^2$ to get $\alpha = 6t$, so $\alpha = 6\,\text{rad/s}^2$ at $t=1$.', '["Step 1: $\\alpha = \\frac{d\\omega}{dt} = 6t$", "Step 2: At $t=1$, $\\alpha = 6\\,\\text{rad/s}^2$"]', '$\alpha = \frac{d\omega}{dt}$', 'physics.rotational.kinematics_derivative_misuse', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:18:55.411Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc9d51eed8b6501a1097e112c35e4284', 'Board', '10', 'Science', 'phy_10_board_electricity', 'Electricity', 'Joule''s heating effect applications', '[]', '["joules heating","ohms law","power","energy calculation"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1600, 'BOARD_HARD', 2, 0.0, 'An electric iron draws a current of 4 A from a 220 V supply. What is the heat produced in 30 seconds?', '["1.76 kJ", "2.64 kJ", "3.52 kJ", "5.28 kJ"]', '2.64 kJ', 'Use $H = I^2Rt$, with $R = V/I$. Substituting values gives correct heat energy.', '["Step 1: $R = 220/4 = 55\\Omega$", "Step 2: $H = (4)^2 \\times 55 \\times 30 = 26400 J$"]', '$H = I^2Rt$', 'physics.electricity.joules_law_formula_mixup', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:19:19', 'v2.1', 'Taxonomy alignment: updated class (10->10), exam (Board->Board), subject (Physics->Science) to match canonical taxonomy item sci_10_board_electricity', '2026-05-22T15:18:20.268Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bc9da1c34dfb0436d51397dab0405bb6', 'NEET', '11', 'Biology', 'bio_11_neet_plant_physiology', 'Plant Physiology Advanced', 'Seed dormancy types and germination triggers light/temperature', '[]', '["seed dormancy","photodormancy","thermodormancy","germination triggers","light requirement","cold stratification","plant development"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 2000, 'NEET_MEDIUM', 4, -1.0, 'Which of the following combinations correctly describes seed dormancy types and their germination triggers?', '["Photodormant seeds require light; thermodormant seeds break dormancy with cold stratification", "Photodormant seeds require darkness; thermodormant seeds need heat", "Thermodormant seeds require light; photodormant seeds need cold", "Dormancy is always broken by high temperature"]', 'Photodormant seeds require light; thermodormant seeds break dormancy with cold stratification', 'Photodormant seeds (e.g., lettuce) need light exposure to germinate. Thermodormant seeds often require a period of cold (stratification) to break dormancy, mimicking winter. Darkness inhibits germination in photodormant seeds. High temperature may break dormancy in some, but not universally. Cold stratification is key for many temperate species.', '["Step 1: Define photodormancy — light-dependent germination", "Step 2: Define thermodormancy — temperature-regulated", "Step 3: Recall cold stratification breaks dormancy in many seeds", "Step 4: Eliminate options with reversed or universal claims"]', '', 'biology.plant.dormancy_trigger_confusion', 'NEET Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:18', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:10:50.821Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bca0fe23e17ccf06d6c26ad059bc9dfa', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_combinatorics', 'Advanced Combinatorics', 'Generating functions', '["math_12_ja_series"]', '["generating-functions","binomial-expansion","coefficient"]', 1, 0, '[]', 'Integer', NULL, 0, 2650, 'JEE_ADV_MEDIUM', 2, -1.0, 'Find coefficient of $x^4$ in expansion of $(1-x)^{-3}$.', '[]', '15', 'Coeff is \\binom{n+2}{2} for $(1-x)^{-3}$. Here n=4, so \\binom{6}{2}=15.', '["Formula: coeff of x^n is \\\\binom{n+2}{2}", "Here n=4", "\\\\binom{6}{2} = 15"]', '(1-x)^{-n} = \\sum \\binom{n+k-1}{k} x^k', 'math.combinatorics.binomial_coeff', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:24', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T14:45:41.003Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bca575d1ad504529f8e86c75ba08d25f', 'NEET', '12', 'Biology', 'bio_12_neet_reproduction_org', 'Reproduction in Organisms', 'Sexual reproduction events phases', '[]', '["sexual reproduction","fertilization","gamete fusion","phases"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1750, 'NEET_EASY', 2, -1.0, 'Which phase of sexual reproduction involves fusion of gametes?', '["Gametogenesis", "Fertilization", "Syngamy", "Embryogenesis"]', 'Fertilization', 'Fertilization is the fusion of male and female gametes.', '["Step 1: Identify gamete fusion event", "Step 2: Recall term for gamete fusion"]', '', 'biology.reproduction.gamete_phase_confusion', 'NEET Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:12:56.145Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bca80463b743fa49b9aa37708d6adc27', 'JEEMains', '12', 'Physics', 'phy_12_jm_modern_physics', 'Dual Nature of Radiation and Matter', 'Atomic spectra', '[]', '["Rydberg constant","hydrogen spectrum","Balmer series","Lyman series","wavelength calculation"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'The wavelength of the first line of the Balmer series of hydrogen is 656.3 nm. Using the Rydberg formula $$\frac{1}{\lambda}=R_{\infty}\left(\frac{1}{n_{1}^{2}}-\frac{1}{n_{2}^{2}}\right)$$, calculate the wavelength of the transition from \(n_{2}=3\) to \(n_{1}=1\) (Lyman series).', '["102.5 nm", "121.6 nm", "97.3 nm", "91.2 nm"]', '102.5 nm', 'Insert \(n_{1}=1\) and \(n_{2}=3\) into the Rydberg formula: \(\frac{1}{\lambda}=R_{\infty}\left(1-\frac{1}{9}\right)=\frac{8}{9}R_{\infty}\). Using \(R_{\infty}=1.097\times10^{7}\,\text{m}^{-1}\) gives \(\lambda=\frac{9}{8R_{\infty}}\approx1.025\times10^{-7}\,\text{m}=102.5\,\text{nm}\).', '["Step 1: Write the Rydberg formula for hydrogen.", "Step 2: Substitute \\(n_{1}=1\\) and \\(n_{2}=3\\).", "Step 3: Simplify to \\(\\frac{1}{\\lambda}=\\frac{8}{9}R_{\\infty}\\).", "Step 4: Invert to obtain \\(\\lambda=\\frac{9}{8R_{\\infty}}\\) and compute the numerical value."]', '\frac{1}{\lambda}=R_{\infty}\left(\frac{1}{n_{1}^{2}}-\frac{1}{n_{2}^{2}}\right)', 'physics.modern_physics.atomic_spectra', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:53:43.558Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcaa5d6a4fc22fbd0e8ead49c8b35a43', 'JEEMains', '12', 'Chemistry', 'chem_12_jee_mains_aldehydes_ketones_and_carboxylic_acids', 'Carbonyl Compounds', 'Baeyer Villiger oxidation of ketones', '[]', '["Baeyer-Villiger oxidation","Ketones","Carbonyl compounds"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 3, -1.0, '$\text{The Baeyer-Villiger oxidation of ketones is a reaction that involves the following steps:}\n\text{Step 1: Formation of a peroxide}\n\text{Step 2: Cleavage of the peroxide}\n\text{Step 3: Formation of an ester}\n\text{Identify the correct step in the Baeyer-Villiger oxidation of ketones.}$', '["Step 1: Formation of a peroxide", "Step 2: Cleavage of the peroxide", "Step 3: Formation of an ester", "Step 4: Formation of an alcohol"]', 'Step 3: Formation of an ester', 'Step 1: Identify the correct step in the Baeyer-Villiger oxidation of ketones.,Step 2: Determine the relationship between the steps in the reaction and the properties of the reactants.,Step 3: Classify the step in the reaction based on the relationship between the steps and the properties of the reactants.', '["Step 1: Identify the correct step in the Baeyer-Villiger oxidation of ketones.", "Step 2: Determine the relationship between the steps in the reaction and the properties of the reactants.", "Step 3: Classify the step in the reaction based on the relationship between the steps and the properties of the reactants."]', '', 'chemistry.aldehydes_ketones_and_carboxylic_acids.baeyer_villiger_oxidation', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:38:32.250Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcb82dfc0e11847c1fababa0b5dd02f8', 'Board', '10', 'Mathematics', 'math_10_board_triangles', 'Triangles', 'Heights and distances tan Î¸ applications', '[]', '["heights and distances","angle of elevation","tangent function","right triangle","trigonometric ratio","real-life application","approximation"]', 0, 0, '["Board"]', 'Integer', NULL, 0, 1600, 'BOARD_HARD', 5, 0.0, 'A person standing 60 meters away from a building observes the top of the building at an angle of elevation of $30^\circ$. The height of the building is approximately:

[Use $\tan 30^\circ = \frac{1}{\sqrt{3}}$]', '[]', '34.64', 'Using $\tan \theta = \frac{\text{opposite}}{\text{adjacent}}$, $\tan 30^\circ = \frac{h}{60}$. So $\frac{1}{\sqrt{3}} = \frac{h}{60}$ → $h = \frac{60}{\sqrt{3}} = 20\sqrt{3} \approx 34.64$ m.', '["Step 1: Draw right triangle: base = 60 m, angle = 30°, height = h.", "Step 2: Apply $\\tan 30^\\circ = \\frac{h}{60}$.", "Step 3: Substitute $\\tan 30^\\circ = \\frac{1}{\\sqrt{3}}$.", "Step 4: Solve: $h = \\frac{60}{\\sqrt{3}} = 20\\sqrt{3}$.", "Step 5: Compute decimal: $20 \\times 1.732 = 34.64$."]', '$\tan \theta = \frac{\text{opposite}}{\text{adjacent}}$', 'math.trigonometry.tan_value_misuse', 'Board Class 10', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:25:58.981Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcc212aea85b11b8caae2d683b49e705', 'JEEMains', '12', 'Physics', 'phy_12_jm_lens', 'Ray Optics', 'Lens maker equation and power', '[]', '["lens maker equation","focal length","refractive index","convex lens","radius of curvature"]', 0, 0, '[]', 'MCQ', NULL, 0, 2000, 'JEE_MAINS_EASY', 4, -1.0, 'A thin convex lens has radii of curvature R₁ = +20 cm and R₂ = –30 cm, and its material has refractive index n = 1.5. What is the focal length of the lens? (Use the lens‑maker formula.)', '["24 cm", "30 cm", "20 cm", "40 cm"]', '24 cm', 'Lens‑maker equation: 1/f = (n‑1)(1/R₁ – 1/R₂). Substituting n = 1.5, R₁ = 20 cm, R₂ = –30 cm gives 1/f = 0.5(0.05 – (‑0.0333)) = 0.0417 cm⁻¹, so f ≈ 24 cm.', '["Step 1: Write the lens‑maker formula: 1/f = (n‑1)(1/R₁ – 1/R₂).", "Step 2: Insert n = 1.5, R₁ = +20 cm, R₂ = –30 cm.", "Step 3: Compute (1/R₁ – 1/R₂) = 0.05 – (‑0.0333) = 0.0833 cm⁻¹.", "Step 4: Multiply by (n‑1) = 0.5 → 0.0417 cm⁻¹.", "Step 5: Invert to obtain f ≈ 24 cm."]', '1/f = (n-1)(1/R1 - 1/R2)', 'physics.optics.lens_maker_error', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:22', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:45:01.319Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcc7bb6a9de7a5c9a052eb99010799f3', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_calculus_advanced', 'Calculus', 'Functions defined by integrals', '["math_12_ja_application_derivatives"]', '["Leibniz rule","fundamental theorem of calculus","chain rule","differentiation under integral","function definition","composite function","derivative"]', 1, 0, '[]', 'MCQ', NULL, 0, 2550, 'JEE_ADV_EASY', 4, -2.0, 'Let $ f(x) = \int_0^{x^2} \sin(t^2)~dt $. Find $ f''(x) $.', '["$ \\sin(x^4) \\cdot 2x $", "$ \\sin(x^2) \\cdot 2x $", "$ \\cos(x^4) \\cdot 2x $", "$ \\sin(x^4) $"]', '$ \sin(x^4) \cdot 2x $', 'By the Fundamental Theorem of Calculus and chain rule: $ \frac{d}{dx} \int_0^{u(x)} g(t)~dt = g(u(x)) \cdot u''(x) $. Here $ u(x) = x^2 $, so $ f''(x) = \sin((x^2)^2) \cdot 2x = \sin(x^4) \cdot 2x $. This combines calculus concepts across functions and integrals.', '["Step 1: Recognize function defined by integral with variable upper limit", "Step 2: Apply Leibniz rule: derivative = integrand evaluated at upper limit × derivative of limit", "Step 3: Upper limit is $ x^2 $, so $ t = x^2 \\Rightarrow t^2 = x^4 $", "Step 4: $ f''(x) = \\sin(x^4) \\cdot 2x $"]', '\frac{d}{dx}\int_0^{u(x)} f(t)~dt = f(u(x)) \cdot u''(x)', 'math.calculus.leibniz_chain_rule_missed', 'JEEAdvanced Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:17', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:59:32.125Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcca0df1555349917e5d19f0ba745ce7', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_surface_langmuir', 'Surface Chemistry', 'Langmuir isotherm', '["chem_12_jm_surface_freundlich"]', '["adsorption","Langmuir constant","monolayer capacity","gas-solid interaction","isotherm calculation"]', 1, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 4, -1.0, 'At 298 K, the adsorption of gas X on a solid follows the Langmuir isotherm given by \( \frac{P}{V} = \frac{1}{V_m} + \frac{P}{V_m K} \). If the monolayer capacity \(V_m\) is 2.5 L and the Langmuir constant \(K\) is 0.20 atm\(^{-1}\), what is the volume adsorbed at a pressure of 0.5 atm?', '["0.23 L", "0.45 L", "0.18 L", "0.30 L"]', '0.23 L', 'Using the Langmuir equation \(V = \frac{V_m K P}{1+K P}\), substitute \(V_m=2.5\) L, \(K=0.20\) atm\(^{-1}\) and \(P=0.5\) atm. The numerator is \(2.5\times0.20\times0.5=0.25\) and the denominator is \(1+0.20\times0.5=1.10\). Hence \(V=0.25/1.10\approx0.227\) L, which rounds to 0.23 L.', '["Step 1: Write the Langmuir adsorption formula \\(V = \\frac{V_m K P}{1+K P}\\).", "Step 2: Substitute the given values \\(V_m=2.5\\) L, \\(K=0.20\\) atm\\(^{-1}\\), \\(P=0.5\\) atm.", "Step 3: Compute numerator \\(2.5\\times0.20\\times0.5=0.25\\) and denominator \\(1+0.20\\times0.5=1.10\\).", "Step 4: Divide to obtain \\(V\\approx0.227\\) L and select the nearest option."]', 'V = \frac{V_m K P}{1+K P}', 'chemistry.adsorption.langmuir_calculation', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:21', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:51:43.139Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcd065213a9ca41c6385dfe0b411dd1e', 'JEEMains', '11', 'Mathematics', 'math_11_jm_binomial', 'Binomial Theorem', 'Coefficient of a specific term', '[]', '["binomial theorem","coefficients","combination","expansion","powers"]', 0, 0, '[]', 'MCQ', NULL, 0, 1900, 'JEE_MAINS_EASY', 4, -1.0, 'In the expansion of \((2x-3)^{5}\), what is the coefficient of \(x^{3}\)?', '["720", "-720", "360", "-360"]', '720', 'The term containing \(x^{3}\) is given by \(\binom{5}{3}(2x)^{3}(-3)^{2}=10\times8x^{3}\times9=720x^{3}\). Hence the coefficient is 720.', '["Step 1: Identify the term with \\(x^{3}\\): \\(k=3\\) in \\((2x-3)^{5}\\).", "Step 2: Compute the binomial coefficient \\(\\binom{5}{3}=10\\).", "Step 3: Evaluate \\((2x)^{3}=8x^{3}\\) and \\((-3)^{2}=9\\).", "Step 4: Multiply 10 \\times 8 \\times 9 = 720."]', '\binom{n}{k}a^{n-k}b^{k}', 'math.algebra.binomial_coefficient', 'JEEMains Class 11', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:55:01.441Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcd1db517a583646d69c68b37e44e279', 'JEEMains', '12', 'Chemistry', 'chem_12_jm_d_and_f_block', 'd and f Block Elements', 'Potassium permanganate preparation reactions', '[]', '["KMnO4 preparation","MnO2 oxidation","fused KOH","KClO3 oxidant"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 2, -1.0, 'Which reagent is used in the laboratory preparation of $KMnO_4$ from $MnO_2$?', '["$K_2Cr_2O_7$", "$KClO_3 + KOH$", "$H_2O_2$", "$O_2$"]', '$KClO_3 + KOH$', '$MnO_2$ is fused with $KOH$ and oxidized by $KClO_3$ to form $K_2MnO_4$, then electrolytically oxidized to $KMnO_4$.', '["Step 1: Recall fusion of $MnO_2$ with $KOH$ and $KClO_3$", "Step 2: Forms green $K_2MnO_4$"]', '', 'chem.inorganic.d_block.preparation_wrong_oxidant', 'JEEMains Class 12', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:13:40.891Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcd30b9603957f20c8de78c552c2be38', 'Board', '9', 'Science', 'sci_9_motion_average', 'Motion', 'Average speed', '[]', '["speed","average speed","distance","time"]', 0, 0, '[]', 'MCQ', NULL, 0, 950, 'CLASS_9_BASIC', 3, 0.0, 'A car travels a distance of $150\,\text{km}$ in $3\,\text{h}$. What is its average speed?', '["50 km/h", "45 km/h", "55 km/h", "60 km/h"]', '50 km/h', 'Average speed = total distance / total time = $150\,\text{km} / 3\,\text{h} = 50\,\text{km/h}$.', '["Step 1: Write the formula $\\text{average speed}=\\frac{\\text{distance}}{\\text{time}}$.", "Step 2: Substitute distance = 150 km and time = 3 h.", "Step 3: Perform the division $150/3 = 50$ km/h."]', 'v_{avg}=\frac{\Delta s}{\Delta t}', 'science.physics.motion.average_speed', 'Board Class 9', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:51:50.590Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcd91b7041d0add89c1ac11238caee0a', 'Board', '10', 'Mathematics', 'math_10_board_polynomials', 'Polynomials', 'Zeros and their graphical significance', '[]', '["zero multiplicity","graph behavior","even multiplicity","root","x‑intercept"]', 0, 0, '[]', 'MCQ', NULL, 0, 1500, 'BOARD_HARD', 3, 0.0, 'If a polynomial $f(x)$ has a zero at $x=2$ of multiplicity 2, what does the graph of $y=f(x)$ do at $x=2$?', '["Crosses the x‑axis and changes sign", "Touches the x‑axis and turns back without crossing", "Has a vertical tangent", "Has a cusp"]', 'Touches the x‑axis and turns back without crossing', 'A zero of even multiplicity causes the graph to touch the x‑axis and rebound, while an odd multiplicity makes it cross. Hence multiplicity 2 (even) leads to a touch without sign change.', '["Step 1: Define multiplicity of a zero.", "Step 2: Recall the graphical behavior for even vs. odd multiplicities.", "Step 3: Apply the rule for multiplicity 2 (even) to select the touching behavior."]', '', 'math.algebra.polynomial_zero_multiplicity', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:50:51.353Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcdc090a5f77534bc3753168f284fcbf', 'JEEAdvanced', '12', 'Physics', 'phy_12_ja_magnetic_force_arbitrary_wire', 'Physics', 'Magnetism', '[]', '["magnetic force","Lorentz force","non‑uniform magnetic field","current loop","vector cross product"]', 1, 0, '[]', 'Multi-correct', NULL, 0, 2700, 'JEE_ADV_MEDIUM', 5, -2.0, 'A rectangular current loop of sides $a$ (along $x$) and $b$ (along $y$) lies in the $xy$‑plane. A non‑uniform magnetic field $\mathbf{B}=k y\,\hat{\mathbf{z}}$ exists. Which statements are correct?

A) The net magnetic force on the loop is zero.
B) The forces on the vertical sides cancel each other.
C) The net force on the loop is directed along the $+y$ direction.
D) The horizontal sides experience forces of equal magnitude but opposite direction.', '["The net magnetic force on the loop is zero.", "The forces on the vertical sides cancel each other.", "The net force on the loop is directed along the $+y$ direction.", "The horizontal sides experience forces of equal magnitude but opposite direction."]', '["THE FORCES ON THE VERTICAL SIDES CANCEL EACH OTHER.", "THE NET FORCE ON THE LOOP IS DIRECTED ALONG THE $+Y$ DIRECTION."]', 'Using $d\mathbf{F}=I\,d\mathbf{l}\times\mathbf{B}$, the vertical sides give equal and opposite $\hat{x}$ forces that cancel. The horizontal sides produce $\hat{y}$ forces of different magnitudes, resulting in a net upward ($+y$) force. Hence statements B and C are correct.', '["Step 1: Write $d\\mathbf{F}=I\\,d\\mathbf{l}\\times\\mathbf{B}$ for each side of the loop.", "Step 2: Evaluate forces on the vertical sides; integrate $I k y\\,dy$ over $y$ to show they cancel.", "Step 3: Compute forces on the horizontal sides; note the dependence on $y$ gives unequal magnitudes.", "Step 4: Sum the $\\hat{y}$ components to obtain a net force $I a k b\\,\\hat{y}$.", "Step 5: Conclude that B and C are the only correct statements."]', 'd\mathbf{F}=I\,d\mathbf{l}\times\mathbf{B}', 'physics.magnetism.force_nonuniform_direction', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:20', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:49:22.401Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcdcd5114554cbc30fe6769f6324bbce', 'Board', '10', 'Mathematics', 'math_10_board_probability', 'Probability', 'Classical probability', '[]', '["classical probability","favourable outcomes","sample space","simplification"]', 0, 0, '[]', 'MCQ', NULL, 0, 1200, 'BOARD_EASY', 3, 0.0, 'A single card is drawn at random from a standard deck of 52 cards. What is the probability that the card is a king?', '["$\\frac{1}{13}$", "$\\frac{1}{4}$", "$\\frac{1}{52}$", "$\\frac{3}{52}$"]', '$\frac{1}{13}$', 'There are 4 kings in a deck of 52 cards. Probability $P = \frac{\text{favourable}}{\text{total}} = \frac{4}{52} = \frac{1}{13}$. The other options stem from mis‑counting or incorrect simplification.', '["Step 1: Count the favourable outcomes (4 kings).", "Step 2: Count the total outcomes (52 cards).", "Step 3: Form the fraction $4/52$ and simplify to $1/13$."]', 'P = \frac{m}{n}', 'math.probability.classical', 'Board Class 10', NULL, 'B', 0.87, 'Recall', '2026-05-23 03:15:23', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T13:50:51.354Z', 1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bcdeb850d4ca49e72e93c2103d796feb', 'NEET', '11', 'Biology', 'bio_11_neet_neural_control', 'Neural Control and Coordination', 'PNS sympathetic parasympathetic', '[]', '["parasympathetic nervous system","autonomic nervous system","rest and digest","sympathetic vs parasympathetic"]', 0, 0, '["Board"]', 'MCQ', NULL, 0, 1800, 'NEET_EASY', 4, -1.0, 'Which of the following effects is associated with parasympathetic nervous system activation?', '["Increased heart rate", "Bronchodilation", "Pupil dilation", "Stimulation of digestion"]', 'Stimulation of digestion', 'The parasympathetic nervous system is responsible for ''rest and digest'' functions. It slows heart rate, constricts pupils, and stimulates digestive secretions and motility. Sympathetic system causes fight-or-flight responses like increased heart rate and bronchodilation.', '["Step 1: Recall that PNS is ''rest and digest'' system.", "Step 2: Identify effects: decreased HR, pupil constriction, increased GI activity.", "Step 3: Compare options: stimulation of digestion is PNS.", "Step 4: Eliminate sympathetic effects: increased HR, bronchodilation, pupil dilation."]', '', 'bio.neural.sympathetic_parasympathetic_swap', 'NEET Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:16', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T11:52:21.472Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bce322b15c2d36b9e1cb5d33707e0a76', 'JEEMains', '11', 'Physics', 'phy_11_jm_uniform_circular', 'Motion in a Plane', 'Uniform Circular Motion', '[]', '["centripetal acceleration","circular motion","radius","speed","v^2/r"]', 0, 0, '[]', 'MCQ', NULL, 0, 2100, 'JEE_MAINS_MEDIUM', 3, -1.0, 'A particle moves in a horizontal circle of radius $0.50\ \text{m}$ with a constant speed of $4.0\ \text{m s}^{-1}$. What is the magnitude of its centripetal acceleration?', '["32 m s^{-2}", "16 m s^{-2}", "8 m s^{-2}", "4 m s^{-2}"]', '32 m s^{-2}', 'Centripetal acceleration is given by $a_c = v^2/r$. Substituting $v = 4.0\ \text{m s}^{-1}$ and $r = 0.50\ \text{m}$ gives $a_c = (4.0)^2 / 0.50 = 16 / 0.50 = 32\ \text{m s}^{-2}$.', '["Step 1: Write the formula $a_c = \\frac{v^2}{r}$.", "Step 2: Substitute $v = 4.0\\ \\text{m s}^{-1}$ and $r = 0.50\\ \\text{m}$.", "Step 3: Compute $a_c = \\frac{(4.0)^2}{0.50} = 32\\ \\text{m s}^{-2}$."]', '$a_c = \frac{v^2}{r}$', 'physics.mechanics.centripetal_acceleration', 'JEEMains Class 11', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:19', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-20T12:36:24.806Z', -1);
INSERT OR IGNORE INTO questions (id, exam, class, subject, primary_topic_id, primary_topic, primary_subtopic, secondary_topic_ids, concept_tags, cross_chapter, cross_subject, also_for, type, passage_id, has_image, difficulty_score, difficulty_band, step_count, negative_marking, question_text, options, correct_answer, explanation, solution_steps, key_formula, error_trap_type, source_exam, year, quality_tier, confidence, cognitive_level, last_repaired_at, repair_version, repair_notes, created_at, verified) VALUES ('bce814239470c84db268ee85658aa5e8', 'JEEAdvanced', '12', 'Mathematics', 'math_12_ja_functions_recursive', 'Functional Equations', 'Recursive function definitions and closed form', '["math_11_ja_sequences_series"]', '["recursion","functional_equation","number_theory","binary_representation","combinatorics"]', 1, 0, '[]', 'Integer', NULL, 0, 2500, 'JEE_ADV_EASY', 3, -1.0, 'A function $f:\mathbb{N}\to\mathbb{N}$ satisfies $f(1)=1$, $f(2n)=f(n)$, $f(2n+1)=f(2n)+1$. What is $f(7)$?', '[]', '3', 'Using recurrence: $f(7)=f(6)+1=f(3)+1=f(2)+2=f(1)+2=3$.', '["Step 1: $f(7)=f(6)+1$, $f(6)=f(3)$", "Step 2: $f(3)=f(2)+1=1+1=2$, so $f(7)=3$"]', 'f(2n+1)=f(2n)+1', 'math.functions.recursion_base_case', 'JEEAdvanced Class 12', NULL, 'D', 0.87, 'Recall', '2026-05-23 03:15:25', 'v2.1', 'Encoding mojibake healed via Phase 1 recursive CP1252 segment decoder and ftfy', '2026-05-22T15:07:32.370Z', -1);
